//! EVEX per-opcode operand tables — generated, do not edit.
//!
//! Regenerate with `python scripts/gen_evex_operands.py`.
//!
//! The destination and disp8 tables come from the operand lists in Bochs's
//! `cpu/decoder/ia_opcodes_evex.def`, where each `OP_*` is
//! `BX_FORM_SRC(type, src)`. The first operand's `src` gives the
//! destination field and the first later ModRM operand's `src` the
//! source field; the memory operand's `type` gives the disp8 scale
//! that `evex_displ8_compression` computes upstream. The test-only
//! operand and immediate counts and executed forms come from the same
//! entries.

use crate::opcode::Opcode;

/// Which ModRM fields name the register an EVEX opcode writes and the
/// register it reads through ModRM.
///
/// Most write the reg field and read rm. The store forms — VEXTRACT*, the
/// truncating VPMOV* stores, VCOMPRESS*, VPEXTR*, VSCATTER* — write rm and
/// read reg, and the shift/rotate-by-immediate groups write EVEX.vvvv and
/// read rm.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum EvexDst {
    Nnn,
    Rm,
    /// Writes rm and reads rm: Bochs TILEMOVROW/TILEMOVCOL `Trm, Wdq`, whose
    /// fetchdecode.h operands `OP_Trm` (`BX_SRC_RM`) and `OP_Wdq`
    /// (`BX_SRC_VECTOR_RM`) both name rm.
    RmSourceRm,
    Vvvv,
}

/// Destination field for an EVEX opcode; the reg field unless listed.
