/// Memory-operand tuple kind, mirroring Bochs's `BX_VMM_*` constants.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum EvexTuple {
    FullVector,
    FullVectorW,
    ScalarByte,
    ScalarWord,
    ScalarDword,
    ScalarQword,
    Scalar,
    HalfVector,
    HalfVectorW,
    QuarterVector,
    QuarterVectorW,
    EighthVector,
    Vec128,
    Vec256,
    Gpr16,
    Gpr32,
    Gpr64,
    None,
}

impl EvexTuple {
    /// N for this operand. Mirrors `evex_displ8_compression`.
    ///
    /// `vl` is 0/1/2 for 128/256/512-bit, so Bochs's `len` (1/2/4) is
    /// `1 << vl`. `broadcast` is EVEX.b with a memory operand.
    pub(crate) const fn scale(self, vl: u8, broadcast: bool, w: bool) -> u32 {
        let len = 1u32 << vl;
        let w4 = if w { 8 } else { 4 };
        match self {
            Self::Gpr64 => 8,
            Self::Gpr32 => 4,
            Self::Gpr16 => 2,
            Self::None => 1,
            Self::FullVector => {
                if broadcast { w4 } else { 16 * len }
            }
            Self::FullVectorW => {
                if broadcast { 2 } else { 16 * len }
            }
            Self::ScalarByte => 1,
            Self::ScalarWord => 2,
            Self::ScalarDword => 4,
            Self::ScalarQword => 8,
            Self::Scalar => w4,
            Self::HalfVector => {
                if broadcast { w4 } else { 8 * len }
            }
            Self::HalfVectorW => {
                if broadcast { 2 } else { 8 * len }
            }
            Self::QuarterVector => 4 * len,
            Self::QuarterVectorW => {
                if broadcast { 2 } else { 4 * len }
            }
            Self::EighthVector => 2 * len,
            Self::Vec128 => 16,
            Self::Vec256 => 32,
        }
    }
}

/// Tuple kind of an EVEX opcode's memory operand, or `None` if it has
/// none (register-only forms never carry a scaled displacement).
